-- LocalBite Seed Data from Master Sheet
-- Generated by scripts/sync_data.js

-- 1. Regions
ON CONFLICT (region_id) DO UPDATE SET
  region_name = EXCLUDED.region_name,
  display_order = EXCLUDED.display_order;

-- 2. Prefectures
ON CONFLICT (prefecture_id) DO UPDATE SET
  region_id = EXCLUDED.region_id,
  prefecture_name = EXCLUDED.prefecture_name;

-- 3. Locations
ON CONFLICT (location_id) DO UPDATE SET
  location_name = EXCLUDED.location_name,
  content_status = EXCLUDED.content_status;

-- 4. Dishes
ON CONFLICT (dish_id) DO UPDATE SET
  dish_name = EXCLUDED.dish_name,
  japanese_name = EXCLUDED.japanese_name,
  summary = EXCLUDED.summary,
  content_status = EXCLUDED.content_status;

-- 5. Dish Locations
ON CONFLICT (dish_id, location_id) DO UPDATE SET
  relationship = EXCLUDED.relationship,
  link_status = EXCLUDED.link_status;
