INSERT INTO dishes (dish_id, dish_name, japanese_name, region_id, primary_prefecture_id, summary, seasons, tags, dietary_guidance, price_min, price_max, content_status, home_filter_tags, vegetarian_status, halal_status, featured, origin_history_preview, origin_history_full, did_you_know, key_ingredients, pronunciation_phonetic, pronunciation_audio_url) VALUES
('aochu', 'Aochu', '青酎', 'kanto', 'tokyo', 'A rare and potent sweet potato shochu crafted on the isolated volcanic island of Aogashima. It offers a rich, earthy flavor with a surprisingly smooth finish.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Vegan, Gluten-free', 2000, 5000, 'Published', ARRAY['Vegetarian', 'Halal']::text[], 'Verified vegetarian', 'Verified halal', true, 'Aochu has been distilled by islanders for generations using locally grown sweet potatoes and a unique natural fermentation process, making it one of Japan''s most exclusive spirits.', NULL, 'Because production is so limited, Aochu is often called the ''phantom shochu'' and is highly sought after by collectors and enthusiasts!', ARRAY['Sweet potatoes, barley koji, water']::text[], 'ah-oh-choo', NULL),
('hingya-no-shio', 'Hingya no Shio', 'ひんぎゃの塩', 'kanto', 'tokyo', 'A premium sea salt crystallized using the geothermal steam from Aogashima''s active volcano. It boasts a complex, mineral-rich taste that enhances any dish.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Vegan, Gluten-free', 500, 1500, 'Published', ARRAY['Vegetarian', 'Halal']::text[], 'Verified vegetarian', 'Verified halal', true, 'The name ''Hingya'' refers to the volcanic steam vents on the island. This salt-making method harnesses the island''s natural geothermal energy, a practice deeply tied to Aogashima''s volcanic landscape.', NULL, 'It takes weeks of slow evaporation over the volcanic vents to produce this salt, resulting in its signature large, crunchy crystals.', ARRAY['Seawater']::text[], 'heen-gyah no shee-oh', NULL),
('haijima-highball', 'Haijima Highball', '拝島ハイボール', 'kanto', 'tokyo', 'A refreshing local highball mixed with distinct local flavors. It''s the perfect thirst-quencher after a day of exploring Akishima!', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Vegan', 400, 800, 'Published', ARRAY['Vegetarian', 'Quick bite', 'Dine-in']::text[], 'Verified vegetarian', 'Not halal', true, 'Created to celebrate the local drinking culture around Haijima Station, this highball has become a beloved staple in the area''s izakayas.', NULL, 'The exact recipe can vary by izakaya, making it a fun local drink to sample and compare as you hop between bars!', ARRAY['Whisky/Shochu, soda water, lemon']::text[], 'hah-ee-jee-mah hye-bohl', NULL),
('haijima-negi-miso', 'Haijima Negi Miso', '拝島ねぎみそ', 'kanto', 'tokyo', 'A savory, umami-packed condiment made from locally grown green onions (negi) blended with rich miso paste. Perfect over warm rice or as a vegetable dip.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Vegan', 300, 800, 'Published', ARRAY['Vegetarian', 'Halal']::text[], 'Verified vegetarian', 'Verified halal', true, 'This rustic condiment highlights the agricultural heritage of the Akishima area, preserving the harvest of sweet winter green onions.', NULL, 'It''s incredibly versatile—locals love to use it as a marinade for grilled meats or simply spread on a crispy rice cracker.', ARRAY['Miso, green onions, sugar, mirin']::text[], 'hah-ee-jee-mah neh-gee mee-so', NULL),
('akigawa-sweet-corn', 'Akigawa Sweet Corn', '秋川とうもろこし', 'kanto', 'tokyo', 'Incredibly sweet and juicy corn grown in the fertile Akigawa Valley. It''s so fresh and tender that it can even be eaten raw!', ARRAY['Summer']::text[], ARRAY['local specialty']::text[], 'Vegan, Gluten-free', 200, 600, 'Published', ARRAY['Vegetarian', 'Halal', 'Quick bite']::text[], 'Verified vegetarian', 'Verified halal', true, 'The pure waters of the Akigawa River and the valley''s distinct temperature differences create the perfect environment for cultivating this premium corn.', NULL, 'During the summer harvest season, you''ll find local farmers boiling or grilling these sweet cobs right by the roadside!', ARRAY['Sweet corn']::text[], 'ah-kee-gah-wah toh-moh-roh-koh-she', NULL),
('norabou-na', 'Norabou-na', 'のらぼう菜', 'kanto', 'tokyo', 'A leafy green vegetable with a tender stem and a mild, sweet flavor, completely free of bitterness. It''s delicious boiled, sautéed, or in soups.', ARRAY['Spring']::text[], ARRAY['local specialty']::text[], 'Vegan, Gluten-free', 150, 400, 'Published', ARRAY['Vegetarian', 'Halal']::text[], 'Verified vegetarian', 'Verified halal', true, 'Norabou-na has been cultivated in the Akiruno area since the Edo period and is celebrated as a vital historical crop that helped locals survive famines.', NULL, 'A local monument in Akiruno honors the magistrate who distributed Norabou-na seeds to farmers during a historical famine!', ARRAY['Norabou-na']::text[], 'noh-rah-boh-nah', NULL),
('bunka-fry', 'Bunka Fry', '文化フライ', 'kanto', 'tokyo', 'A nostalgic, crispy deep-fried snack made from a simple wheat flour batter, often enjoyed with a generous drizzle of sweet and savory sauce.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains wheat, soy', 100, 300, 'Published', ARRAY['Quick bite']::text[], 'Not vegetarian', 'Not halal', true, 'Originating in the post-war Showa era, Bunka Fry was a popular, affordable treat sold at local candy stores (dagashiya) and festivals in Tokyo''s downtown (shitamachi) areas.', NULL, 'Despite the name ''fry,'' it doesn''t contain any meat! It''s a purely flour-based snack that brings back childhood memories for many locals.', ARRAY['Wheat flour, breadcrumbs, sauce']::text[], 'boon-kah foo-rye', NULL),
('senju-no-suzumeyaki', 'Senju no Suzumeyaki', '千住のすずめ焼き', 'kanto', 'tokyo', 'Small, butterflied freshwater fish (typically crucian carp) skewered, glazed in a sweet soy sauce, and grilled to caramelized perfection.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains fish, soy', 500, 1200, 'Published', ARRAY['Dine-in']::text[], 'Not vegetarian', 'Not halal', true, 'This traditional dish dates back to the Edo period when the Senju area was a bustling post town. The dish got its name because the small grilled fish resembled sparrows (suzume) on a wire.', NULL, 'True to its name, ''Suzumeyaki'' means ''grilled sparrow,'' but don''t worry—it''s actually just delicious, crispy river fish!', ARRAY['Small fish (crucian carp/loach), soy sauce, mirin']::text[], 'sen-joo no soo-zoo-meh-yah-kee', NULL),
('yarikake-dango', 'Yarikake Dango', '槍かけだんご', 'kanto', 'tokyo', 'Chewy, freshly pounded rice dumplings skewered and coated in either sweet red bean paste or a savory soy sauce glaze.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Vegan, Gluten-free', 150, 500, 'Published', ARRAY['Vegetarian', 'Halal', 'Quick bite']::text[], 'Verified vegetarian', 'Verified halal', true, 'These historic dangos have been served near the local shrine for centuries. Legend has it that a famous samurai rested his spear (yari) on a pine tree here while enjoying the dumplings.', NULL, 'The shop that sells these has been in business for over 200 years, making it a true taste of Edo-period Tokyo!', ARRAY['Rice flour, soy sauce, sugar, red bean paste']::text[], 'yah-ree-kah-keh dahn-goh', NULL),
('yuyu-toden-wagashi', 'Yuyu Toden - Wagashi', 'ゆうゆう都電（和菓子）', 'kanto', 'tokyo', 'A delightful traditional Japanese sweet (wagashi) shaped like the charming streetcars of the Arakawa Line. It''s as cute as it is delicious!', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Vegan, contains wheat', 200, 600, 'Published', ARRAY['Vegetarian', 'Halal', 'Quick bite']::text[], 'Verified vegetarian', 'Verified halal', true, 'Created to honor the Tokyo Sakura Tram (Toden Arakawa Line), one of the last remaining streetcar lines in Tokyo, this sweet celebrates the nostalgic charm of the area.', NULL, 'It makes for a perfect, photogenic souvenir to enjoy while riding the historic streetcar through Tokyo''s retro neighborhoods.', ARRAY['Sweet bean paste, rice flour, sugar']::text[], 'yoo-yoo toh-den wah-gah-she', NULL),
('arakawa-monja', 'Arakawa Monja', 'あらかわもんじゃ', 'kanto', 'tokyo', 'A savory, gooey pan-fried batter mixed with cabbage, seafood, and meat. You cook it yourself on a hot iron griddle right at your table!', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains wheat, soy, various toppings', 800, 2000, 'Published', ARRAY['Dine-in']::text[], 'Not vegetarian', 'Not halal', true, 'While Tsukishima is famous for Monjayaki, Arakawa Ward is actually considered by many to be the true birthplace of this fun, interactive downtown Tokyo dish.', NULL, 'Eating Monja is a communal experience! You use a tiny metal spatula called a ''hagashi'' to scrape the crispy, caramelized bits off the grill.', ARRAY['Flour, dashi, cabbage, various meats/seafood']::text[], 'ah-rah-kah-wah mon-jah', NULL),
('okara-soy-milk-karinto', 'Okara & Soy Milk Karinto', 'おからと豆乳のかりんとう', 'kanto', 'tokyo', 'A crunchy, subtly sweet snack made with tofu byproducts (okara) and soy milk. It''s a healthier, lighter take on traditional Japanese fried dough cookies.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Vegan, contains soy, wheat', 300, 700, 'Published', ARRAY['Vegetarian', 'Halal', 'Quick bite']::text[], 'Verified vegetarian', 'Verified halal', true, 'Developed by local tofu shops looking to reduce waste, this snack transforms nutrient-rich okara into a delicious, eco-friendly treat.', NULL, 'Okara is incredibly high in fiber, making these crunchy little snacks a guilt-free indulgence!', ARRAY['Okara, soy milk, flour, sugar, oil']::text[], 'oh-kah-rah to toh-nyoo no kah-reen-toh', NULL),
('niku-no-marusan-homemade-ham-cutlet', 'Niku no Marusan Homemade Ham Cutlet', '肉のマルサン 自家製ハムカツ', 'kanto', 'tokyo', 'A thick slice of savory ham coated in crispy panko breadcrumbs and deep-fried to golden perfection. A quintessential Japanese butcher shop snack!', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains meat, wheat, egg', 150, 400, 'Published', ARRAY['Quick bite']::text[], 'Not vegetarian', 'Not halal', true, 'Ham cutlets (hamu-katsu) became a staple of Japanese butcher shops in the Showa era, offering a cheap, hearty, and delicious bite for students and workers.', NULL, 'The best way to eat it is piping hot, right out of a paper bag, while strolling through a local shopping street (shotengai).', ARRAY['Ham, flour, egg, breadcrumbs']::text[], 'nee-koo no mah-roo-sahn hah-moo-kah-tsoo', NULL),
('inagi-pears', 'Inagi Pears', '稲城の梨', 'kanto', 'tokyo', 'Exceptionally large, crisp, and incredibly juicy Japanese pears (nashi). They offer a perfect balance of sweetness and refreshing tartness.', ARRAY['Autumn']::text[], ARRAY['local specialty']::text[], 'Vegan, Gluten-free', 500, 3000, 'Published', ARRAY['Vegetarian', 'Halal', 'Quick bite']::text[], 'Verified vegetarian', 'Verified halal', true, 'Inagi City has a long history of pear cultivation, with local orchards passing down specialized growing techniques for generations to produce these giant fruits.', NULL, 'Some Inagi pears grow so large they can weigh over a kilogram! They are highly prized and often given as luxury gifts.', ARRAY['Japanese pear']::text[], 'ee-nah-gee no nah-she', NULL),
('inagi-mukashibanashi-manju', 'Inagi Mukashibanashi Manju', '稲城の昔ばなしまんじゅう', 'kanto', 'tokyo', 'Soft, steamed buns filled with sweet red bean paste, inspired by local folktales. A comforting and traditional Japanese confection.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Vegan, contains wheat', 150, 500, 'Published', ARRAY['Vegetarian', 'Halal', 'Quick bite']::text[], 'Verified vegetarian', 'Verified halal', true, 'These sweets were created to celebrate the rich folklore and local legends of the Inagi area, bringing traditional stories to life through food.', NULL, 'Mukashibanashi'' means ''old folktales.'' Eating these sweets is a sweet way to connect with the charming local myths of the city.', ARRAY['Flour, red bean paste, sugar']::text[], 'ee-nah-gee moo-kah-she-bah-nah-she mahn-joo', NULL),
('komatsuna', 'Komatsuna', '小松菜', 'kanto', 'tokyo', 'A versatile, dark leafy green that is crisp, mildly sweet, and packed with nutrients. It''s a staple in Japanese soups, stir-fries, and side dishes.', ARRAY['Winter']::text[], ARRAY['local specialty']::text[], 'Vegan, Gluten-free', 100, 300, 'Published', ARRAY['Vegetarian', 'Halal']::text[], 'Verified vegetarian', 'Verified halal', true, 'Named after the Komatsugawa area in Edogawa Ward, this vegetable was famously named by the 8th Tokugawa Shogun during a falconry trip in the Edo period.', NULL, 'Komatsuna is one of the few vegetables that can be grown and harvested year-round in the Tokyo area!', ARRAY['Komatsuna']::text[], 'koh-mah-tsoo-nah', NULL),
('salad-komatsuna', 'Salad Komatsuna', 'サラダ小松菜', 'kanto', 'tokyo', 'A specially cultivated variety of Komatsuna that is so tender and mild it can be eaten completely raw in salads, offering a fresh, crisp crunch.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Vegan, Gluten-free', 150, 400, 'Published', ARRAY['Vegetarian', 'Halal']::text[], 'Verified vegetarian', 'Verified halal', true, 'Developed by modern farmers in Edogawa Ward to appeal to contemporary tastes, this variety highlights the ongoing innovation in Tokyo''s urban agriculture.', NULL, 'Unlike traditional Komatsuna, which usually requires brief boiling, this salad variety saves prep time and retains all its raw vitamins!', ARRAY['Salad Komatsuna']::text[], 'sah-rah-dah koh-mah-tsoo-nah', NULL),
('ome-senbei', 'Ome Senbei', '青梅せんべい', 'kanto', 'tokyo', 'A slightly sweet, elegantly curved rice cracker that is crisp and light. It pairs perfectly with a hot cup of Japanese green tea.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Vegan, contains wheat', 300, 1000, 'Published', ARRAY['Vegetarian', 'Halal', 'Quick bite']::text[], 'Verified vegetarian', 'Verified halal', true, 'These crackers have been a beloved local souvenir in Ome City since the Showa era, traditionally shaped to resemble the curved profile of a plum (ome) blossom petal.', NULL, 'The distinctive curved shape is carefully crafted by hand-pressing the crackers while they are still warm from the oven!', ARRAY['Wheat flour, sugar, eggs']::text[], 'oh-meh sen-bay', NULL),
('noshikon', 'Noshikon', 'のしこん', 'kanto', 'tokyo', 'A unique, thinly stretched konjac (konnyaku) delicacy. It has a satisfyingly chewy texture and absorbs the flavors of whatever broth it''s cooked in.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Vegan, Gluten-free', 200, 500, 'Published', ARRAY['Vegetarian', 'Halal']::text[], 'Verified vegetarian', 'Verified halal', true, 'Traditional konjac making has deep roots in the mountainous Ome region, where the pure water is ideal for processing the konjac potato.', NULL, 'Konjac is famously known as ''a broom for the stomach'' in Japan because it''s high in fiber and almost zero calories!', ARRAY['Konjac yam flour']::text[], 'noh-she-kon', NULL),
('bekko-sushi', 'Bekko Sushi', 'べっこう寿司', 'kanto', 'tokyo', 'An island specialty featuring slices of fresh white fish marinated in a fiery, soy-sauce-and-green-chili mixture, served over vinegared sushi rice.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains fish, soy', 1000, 2000, 'Published', ARRAY['Dine-in']::text[], 'Not vegetarian', 'Not halal', true, 'Originating in the Izu Islands, this spicy marinade was developed as a way to preserve the local catch in the days before refrigeration.', NULL, 'The dish is named ''Bekko'' (tortoiseshell) because the chili-soy marinade gives the fish a beautiful, glossy amber color!', ARRAY['White fish, soy sauce, green chilies, vinegared rice']::text[], 'bek-koh zoo-she', NULL),
('zako-teishoku', 'Zako Teishoku', 'ざこ定食', 'kanto', 'tokyo', 'A rustic, hearty set meal featuring a variety of small, locally caught reef fish, usually served fried or simmered, alongside rice and miso soup.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains fish, soy', 800, 1500, 'Published', ARRAY['Dine-in']::text[], 'Not vegetarian', 'Not halal', true, 'This meal reflects the traditional, everyday diet of the island''s fishermen, utilizing the diverse and abundant small fish found in Oshima''s coastal waters.', NULL, 'Zako'' literally means ''small miscellaneous fish.'' It''s a sustainable and delicious way to enjoy the day''s freshest, most authentic local catch!', ARRAY['Various small fish, rice, miso']::text[], 'zah-koh tay-shoh-koo', NULL),
('gyunu-senbei', 'Gyunu Senbei', '牛乳せんべい', 'kanto', 'tokyo', 'A crisp, slightly sweet cracker made with rich local milk. It has a gentle, milky aroma and a satisfying crunch that appeals to all ages.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains dairy, wheat, egg', 400, 1000, 'Published', ARRAY['Vegetarian', 'Halal', 'Quick bite']::text[], 'Verified vegetarian', 'Verified halal', true, 'Oshima Island has a surprising history of dairy farming. These crackers were created to showcase the high quality of the island''s milk production.', NULL, 'They are baked without using any water—just pure island milk, butter, and flour—giving them their distinctively rich flavor!', ARRAY['Wheat flour, sugar, milk, eggs']::text[], 'gyoo-nyoo sen-bay', NULL),
('omori-nori', 'Omori Nori', '大森の海苔', 'kanto', 'tokyo', 'High-quality, crisp roasted seaweed with a deep, savory ocean flavor. It''s the perfect wrapper for sushi or onigiri (rice balls).', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Vegan, Gluten-free', 500, 3000, 'Published', ARRAY['Vegetarian', 'Halal']::text[], 'Verified vegetarian', 'Verified halal', true, 'During the Edo period, the Omori coastal area was the premier producer of seaweed for the Shogun''s capital, famous for pioneering nori aquaculture.', NULL, 'Although commercial harvesting in Omori ended in the 1960s, the area''s historic wholesale shops still roast and sell some of the best nori in Japan!', ARRAY['Seaweed (Nori)']::text[], 'oh-moh-ree no-ree', NULL),
('shima-zushi', 'Shima-zushi', '島寿司', 'kanto', 'tokyo', 'A tropical take on sushi! Fresh island fish is marinated in a sweet soy glaze and served on rice with a dab of spicy mustard instead of wasabi.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains soy, gluten, fish', 1000, 2500, 'Published', ARRAY['Dine-in']::text[], 'Not vegetarian', 'Not halal', true, 'Because the remote Ogasawara Islands couldn''t grow wasabi, settlers adapted by using fiery mustard (karashi) to flavor their preserved sushi.', NULL, 'The sweet soy marinade gives the fish a glossy sheen, and the kick of the mustard pairs perfectly with the warm island climate!', ARRAY['Wahoo (Sawara), soy sauce, mirin, sugar, rice, mustard']::text[], 'shee-mah zoo-she', NULL),
('kame-ni', 'Kame-ni', '亀煮', 'kanto', 'tokyo', 'A traditional, savory stew made from sea turtle meat, simmered slowly with soy sauce, sake, and vegetables until deeply flavorful.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains turtle meat', 800, 2000, 'Published', ARRAY['Dine-in']::text[], 'Not vegetarian', 'Not halal', true, 'Sea turtles were a crucial protein source for the early settlers of these remote islands. Today, the catch is strictly limited and regulated for conservation.', NULL, 'Eating sea turtle is a rare cultural experience in Japan, permitted only in Ogasawara under strict annual quotas to preserve local heritage.', ARRAY['Green turtle meat/offal, salt, onions, soy sauce']::text[], 'kah-meh nee', NULL),
('same-burger', 'Same Burger', 'サメバーガー', 'kanto', 'tokyo', 'A unique island fast-food treat featuring a crispy, fried shark meat patty served on a soft bun with fresh lettuce and tangy sauce.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains fish, gluten, egg', 600, 1200, 'Published', ARRAY['Quick bite', 'Dine-in']::text[], 'Not vegetarian', 'Not halal', true, 'Utilizing locally caught shark, this burger was created as a fun, accessible way for visitors to taste the diverse marine life of the Ogasawara waters.', NULL, 'Shark meat is surprisingly mild, flaky, and tender—making it an incredibly delicious and sustainable alternative to traditional fish burgers!', ARRAY['Thresher shark, flour, breadcrumbs, buns, lettuce, tartar sauce']::text[], 'sah-meh bah-gah', NULL),
('shikaku-mame-tempura', 'Shikaku-mame Tempura', '四角豆の天ぷら', 'kanto', 'tokyo', 'Winged beans (shikaku-mame) coated in a light batter and deep-fried to a crisp. They offer a delightful crunch and a fresh, green flavor.', ARRAY['Summer']::text[], ARRAY['local specialty']::text[], 'Contains gluten, fried in oil', 500, 1000, 'Published', ARRAY['Vegetarian', 'Quick bite', 'Dine-in']::text[], 'Verified vegetarian', 'Not halal', true, 'The winged bean thrives in Ogasawara''s subtropical climate and has become a staple agricultural product of the islands.', NULL, 'Shikaku'' means square in Japanese, referring to the unique four-angled, frilly shape of this tropical bean!', ARRAY['Winged beans (Shikaku-mame), tempura batter, oil']::text[], 'she-kah-koo mah-meh ten-poo-rah', NULL),
('akaba-miso-soup', 'Akaba Miso Soup', 'アカバの味噌汁', 'kanto', 'tokyo', 'A comforting, umami-rich miso soup made with the broth of the ''Akaba'' (a local red grouper), often served with the fish head or cuts of meat.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains fish, soy', 600, 1500, 'Published', ARRAY['Dine-in']::text[], 'Not vegetarian', 'Not halal', true, 'The Akaba fish is a prized catch in the Ogasawara Islands, and making soup from its bones is a traditional way to utilize the entire fish.', NULL, 'The collagen from the fish gives the soup a rich, slightly thick texture that is both delicious and great for your skin!', ARRAY['Akaba (Red Grouper), miso paste, water, onions']::text[], 'ah-kah-bah mee-so soo-poo', NULL),
('shima-lemon-jelly', 'Shima Lemon Jelly', '島レモンゼリー', 'kanto', 'tokyo', 'A refreshing, sweet-and-sour dessert made with the juice of Ogasawara''s distinctively large, green island lemons.', ARRAY['Autumn']::text[], ARRAY['local specialty']::text[], 'Vegan (if agar used)', 300, 600, 'Published', ARRAY['Vegetarian', 'Halal', 'Quick bite', 'Dine-in']::text[], 'Verified vegetarian', 'Verified halal', true, 'Ogasawara lemons were introduced to the islands in the 19th century. They are uniquely sweet and lack the harsh bitterness of standard lemons.', NULL, 'Because the island lemons are so mild, you can even eat the rind! This jelly captures the pure, tropical essence of the fruit.', ARRAY['Shima Lemon juice, sugar, gelatin or agar, water']::text[], 'she-mah reh-mon zeh-ree', NULL),
('okutama-yamame', 'Okutama Yamame', '奥多摩やまめ', 'kanto', 'tokyo', 'A premium, mountain river trout with incredibly tender, sweet pink flesh. It is spectacular when salt-grilled over an open charcoal fire.', ARRAY['Summer']::text[], ARRAY['local specialty']::text[], 'Contains fish', 1000, 3000, 'Published', ARRAY['Dine-in']::text[], 'Not vegetarian', 'Not halal', true, 'The pristine, icy rivers of the Okutama mountains provide the perfect habitat for the Yamame, which has been prized by locals for centuries.', NULL, 'Yamame is often called the ''Queen of the Mountain Streams'' due to its beautiful markings and elegant, delicate flavor.', ARRAY['Okutama Yamame (Masu Salmon), salt']::text[], 'oh-koo-tah-mah yah-mah-meh', NULL),
('okutama-wasabi', 'Okutama Wasabi', '奥多摩わさび', 'kanto', 'tokyo', 'Freshly grated, vibrant green wasabi root. It delivers a sharp, clean heat that quickly dissipates, revealing a subtle, natural sweetness.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Vegan, Gluten-free', 500, 2000, 'Published', ARRAY['Vegetarian', 'Halal', 'Quick bite', 'Dine-in']::text[], 'Verified vegetarian', 'Verified halal', true, 'Okutama''s pure spring water and cool mountain climate have made it one of Tokyo''s premier wasabi-growing regions since the Edo period.', NULL, 'Real, freshly grated wasabi loses its flavor within 15 minutes, which is why it''s a luxury meant to be eaten immediately!', ARRAY['Fresh Wasabi root']::text[], 'oh-koo-tah-mah wah-sah-bee', NULL),
('sashimi-konnyaku', 'Sashimi Konnyaku', '刺身こんにゃく', 'kanto', 'tokyo', 'Thin, translucent slices of handmade konjac jelly, served chilled with a side of sweet miso or soy sauce. A refreshing and healthy appetizer.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Vegan, Gluten-free (depending on sauce)', 400, 900, 'Published', ARRAY['Vegetarian', 'Halal', 'Quick bite', 'Dine-in']::text[], 'Verified vegetarian', 'Verified halal', true, 'Made using pure Okutama mountain water and locally grown konjac potatoes, this dish showcases the pristine natural resources of the region.', NULL, 'Unlike the firm konjac used in stews, ''sashimi'' konjac is specially crafted to be incredibly soft and melt-in-your-mouth tender!', ARRAY['Konjac yam flour, Okutama spring water']::text[], 'sah-shee-mee kon-nyah-koo', NULL),
('kusa-dango', 'Kusa Dango', '草だんご', 'kanto', 'tokyo', 'Chewy rice dumplings infused with the earthy, spring flavor of mugwort (yomogi), generously topped with sweet red bean paste.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Vegan, Gluten-free (typically)', 150, 600, 'Published', ARRAY['Vegetarian', 'Halal', 'Quick bite', 'Dine-in']::text[], 'Verified vegetarian', 'Verified halal', true, 'These vibrant green sweets are famously associated with the Shibamata area and the beloved Japanese film series ''Otoko wa Tsurai yo.''', NULL, 'The mugwort gives the dumplings their bright green color and is traditionally believed to ward off evil spirits!', ARRAY['Rice flour (Joshinko/Shiratamako), Mugwort (Yomogi), sweet red bean paste (Anko)']::text[], 'koo-sah dahn-goh', NULL),
('kawazakana-ryori', 'Kawazakana Ryori', '川魚料理', 'kanto', 'tokyo', 'Traditional river fish cuisine, featuring delicacies like grilled eel (unagi) and simmered carp (koi), served in historic, atmospheric restaurants.', ARRAY['Summer']::text[], ARRAY['local specialty']::text[], 'Contains fish, soy, wheat', 2500, 6000, 'Published', ARRAY['Dine-in']::text[], 'Not vegetarian', 'Not halal', true, 'Located along the Edogawa River, Katsushika has a centuries-old tradition of river fishing, catering to travelers and pilgrims visiting local temples.', NULL, 'Many of the river fish restaurants in this area have been operating in beautiful, traditional wooden buildings for over 200 years!', ARRAY['Freshwater Eel (Unagi), Carp (Koi), soy sauce, mirin, sugar, rice']::text[], 'kah-wah-zah-kah-nah ryoh-ree', NULL),
('motsuyaki', 'Motsuyaki', 'もつ焼き', 'kanto', 'tokyo', 'Skewers of grilled pork or beef offal, glazed in a rich, savory-sweet tare sauce or simply salted. A quintessential Tokyo street food!', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains meat (pork/beef)', 100, 500, 'Published', ARRAY['Quick bite', 'Dine-in']::text[], 'Not vegetarian', 'Not halal', true, 'Motsuyaki became a vital, affordable source of protein in Tokyo''s working-class neighborhoods (shitamachi) during the post-war rebuilding era.', NULL, 'It pairs perfectly with a ''hoppy''—a retro, beer-like beverage that is a staple of Tokyo''s downtown drinking culture!', ARRAY['Pork or beef offal, salt, tare (soy-based glaze)']::text[], 'moh-tsoo-yah-kee', NULL),
('takinogawa-gobo', 'Takinogawa Gobo', '滝野川ごぼう', 'kanto', 'tokyo', 'A traditional variety of burdock root known for its exceptional length, earthy aroma, and satisfying crunch. Often served braised or in salads.', ARRAY['Autumn']::text[], ARRAY['local specialty']::text[], 'Vegan, Gluten-free', 500, 1500, 'Published', ARRAY['Vegetarian', 'Halal', 'Dine-in']::text[], 'Verified vegetarian', 'Verified halal', true, 'This specific variety of burdock was developed in the Takinogawa area during the Edo period and became the ancestor of most burdock grown in Japan today.', NULL, 'These roots can grow up to a meter long! Harvesting them requires incredible skill to pull them from the earth without breaking them.', ARRAY['Takinogawa Gobo (Burdock Root)']::text[], 'tah-kee-noh-gah-wah goh-boh', NULL),
('kiyose-bo', 'Kiyose Bo', 'きよせ棒', 'kanto', 'tokyo', 'A long, baked sweet treat or bread stick, locally crafted and loved for its simple, comforting flavor and satisfying crunch.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains soy, wheat', 410, 410, 'Published', ARRAY['Quick bite']::text[], 'Not vegetarian', 'Not halal', true, 'Created by local bakeries as a playful, easy-to-eat snack, it represents the charming, community-focused food culture of Kiyose City.', NULL, 'Its long, stick-like shape makes it a favorite snack for kids walking home from school in the neighborhood!', ARRAY['Puffed corn snack, Kiyose carrot powder, Kiyose burdock powder, kinpira seasoning']::text[], 'kee-yoh-seh boh', NULL),
('kiyose-man', 'Kiyose Man', '清瀬まん', 'kanto', 'tokyo', 'A soft, fluffy steamed bun filled with a generous portion of sweet, smooth red bean paste. A classic, heartwarming Japanese confection.', ARRAY['Autumn']::text[], ARRAY['local specialty']::text[], 'Contains wheat, meat, soy', 350, 350, 'Published', ARRAY['Quick bite']::text[], 'Not vegetarian', 'Not halal', true, 'These local manju (steamed buns) are a staple at Kiyose City festivals and gatherings, symbolizing community warmth and hospitality.', NULL, 'The name is a simple, affectionate abbreviation of ''Kiyose Manju,'' making it a recognizable and beloved local brand!', ARRAY['Wheat flour dough, minced meat, Kiyose sweet corn, Kiyose carrots, curry spices']::text[], 'kee-yoh-seh mahn', NULL),
('kunitachi-brewery-craft-beer', 'Kunitachi Brewery Craft Beer', 'くにぶる', 'kanto', 'tokyo', 'Artisanal craft beer brewed locally in Kunitachi, featuring a variety of styles from crisp pilsners to rich, aromatic IPAs.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Vegan', 600, 1500, 'Published', ARRAY['Vegetarian', 'Quick bite', 'Dine-in']::text[], 'Verified vegetarian', 'Not halal', true, 'Kuniburu'' is part of the modern wave of Japanese craft brewing, reviving the local tradition of craftsmanship in the heart of Tokyo''s western suburbs.', NULL, 'The brewery often incorporates local fruits and botanicals into their seasonal batches, offering a true taste of the local terroir!', ARRAY['Malt, hops, water, yeast']::text[], 'koo-nee-boo-roo', NULL),
('kinmedai-no-nitsuke', 'Kinmedai no Nitsuke', '金目鯛の煮付け', 'kanto', 'tokyo', 'A luxurious dish of Splendid Alfonsino (a deep-sea red fish) simmered whole in a rich, sweet, and savory soy-sauce broth.', ARRAY['Winter']::text[], ARRAY['local specialty']::text[], 'Contains fish, soy, wheat', 2000, 5000, 'Published', ARRAY['Dine-in']::text[], 'Not vegetarian', 'Not halal', true, 'Kozushima is famous for its abundant catches of Kinmedai. Simmering the fish in a sweet soy glaze is the classic island method to highlight its fatty, tender meat.', NULL, 'The fish''s name, ''Kinmedai,'' translates to ''golden eye,'' referring to its huge, reflective eyes adapted for the deep, dark ocean!', ARRAY['Kinmedai (Splendid Alfonsino), soy sauce, mirin, sake, sugar, ginger']::text[], 'keen-meh-dye no nee-tsoo-keh', NULL),
('toyosu-market-kaisendon', 'Toyosu Market Kaisendon', '豊洲市場の海鮮丼', 'kanto', 'tokyo', 'The ultimate seafood bowl! A bed of sushi rice piled high with the freshest, most vibrant sashimi straight from the morning''s fish auctions.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains fish, soy, wheat', 2000, 6000, 'Published', ARRAY['Dine-in']::text[], 'Not vegetarian', 'Not halal', true, 'Following the closure of the historic Tsukiji inner market, Toyosu became the new hub for Tokyo''s seafood, continuing the legacy of world-class sushi breakfasts.', NULL, 'The chefs at the market restaurants often have first pick of the day''s catch, ensuring your bowl has the highest quality fish in the world!', ARRAY['Tuna (Maguro), Sea Urchin (Uni), Salmon roe (Ikura), seasonal fish, vinegared rice']::text[], 'toh-yoh-soo ee-chee-bah no kye-sen-don', NULL),
('koganei-sakura-junmai-ginjo', 'Koganei Sakura Junmai Ginjo', '小金井桜純米吟醸', 'kanto', 'tokyo', 'A refined, smooth Japanese sake with a delicate floral aroma and a crisp finish, perfect for pairing with traditional Japanese cuisine.', ARRAY['Spring']::text[], ARRAY['local specialty']::text[], 'Vegan, Gluten-free', 1500, 4000, 'Published', ARRAY['Vegetarian', 'Halal']::text[], 'Verified vegetarian', 'Verified halal', true, 'Named after the famous cherry blossoms (sakura) of Koganei Park, this sake celebrates the city''s beautiful springtime scenery.', NULL, 'Junmai Ginjo'' means the sake is brewed using only water, koji mold, and rice that has been highly polished to ensure a pure, premium flavor.', ARRAY['Rice, water, koji']::text[], 'koh-gah-nay sah-koo-rah joon-my geen-joh', NULL),
('fight-monaka', 'Fight Monaka', 'ファイトもなか', 'kanto', 'tokyo', 'A fun, boxing-glove-shaped wafer crisp filled with sweet, dense red bean paste. It''s a knockout dessert that is both tasty and playful!', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Vegan, contains wheat', 200, 500, 'Published', ARRAY['Vegetarian', 'Halal', 'Quick bite']::text[], 'Verified vegetarian', 'Verified halal', true, 'Created to support a local boxing gym and its athletes, this unique sweet has become a quirky and beloved symbol of Kokubunji City.', NULL, 'It''s a popular gift for students taking exams or anyone facing a challenge, given as a sweet way to say ''Do your best!''', ARRAY['Sweet bean paste, wafer shell']::text[], 'fye-toh moh-nah-kah', NULL),
('kate-udon', 'Kate Udon', '糧うどん', 'kanto', 'tokyo', 'Chewy, hand-made udon noodles served cold with a warm, soy-based dipping broth, accompanied by seasonal boiled vegetables.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains wheat, soy, fish (broth)', 800, 1500, 'Published', ARRAY['Dine-in']::text[], 'Not vegetarian', 'Not halal', true, 'Historically, wheat was grown in this region instead of rice. ''Kate'' refers to the seasonal vegetables added to the dish to make the precious noodles last longer.', NULL, 'The noodles have a slightly greyish tint and a robust, earthy wheat flavor that sets them apart from standard, mass-produced udon!', ARRAY['Wheat flour, seasonal vegetables, dashi']::text[], 'kah-teh oo-don', NULL),
('komae-honey', 'Komae Honey', '狛江はちみつ', 'kanto', 'tokyo', 'Pure, locally harvested honey with a delicate, floral sweetness. It captures the essence of the seasonal flowers blooming along the Tama River.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Vegetarian, Gluten-free', 800, 2500, 'Published', ARRAY['Vegetarian', 'Halal']::text[], 'Verified vegetarian', 'Verified halal', true, 'Beekeeping in Komae City is a testament to the area''s rich natural environment, balancing urban living with flourishing green spaces.', NULL, 'Because the bees forage on a variety of local seasonal flowers, the flavor and color of the honey change slightly with every harvest!', ARRAY['Honey']::text[], 'koh-mah-eh hah-chee-mee-tsoo', NULL),
('sable-manju-komae', 'Sable Manju Komae', 'サブレー万頭こまえ', 'kanto', 'tokyo', 'A creative fusion pastry! It combines the crumbly, buttery texture of a Western sable cookie with the sweet red bean filling of a Japanese manju.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains wheat, dairy, egg', 150, 400, 'Published', ARRAY['Vegetarian', 'Halal', 'Quick bite']::text[], 'Verified vegetarian', 'Verified halal', true, 'This modern sweet was designed to bridge the gap between traditional Japanese confectionery and Western baking, reflecting Tokyo''s culinary evolution.', NULL, 'It''s the perfect treat if you can''t decide between a cookie and a traditional Japanese sweet—you get the best of both worlds!', ARRAY['Flour, butter, egg, sweet bean paste']::text[], 'sah-boo-reh mahn-joo koh-mah-eh', NULL),
('komae-jomon-madeleine', 'Komae Jomon Madeleine', 'こまえ縄文マドレーヌ', 'kanto', 'tokyo', 'A soft, buttery sponge cake baked in a unique shape inspired by ancient pottery. It''s a rich, comforting treat with a hint of local history.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains wheat, dairy, egg', 200, 500, 'Published', ARRAY['Vegetarian', 'Halal', 'Quick bite']::text[], 'Verified vegetarian', 'Verified halal', true, 'Komae is home to several ancient Jomon period archaeological sites. This sweet was created to celebrate the city''s prehistoric heritage.', NULL, 'The madeleines are often patterned to resemble the distinctive ''cord-marked'' designs found on ancient Jomon pottery!', ARRAY['Flour, butter, sugar, eggs']::text[], 'koh-mah-eh joh-mon mah-doh-reh-noo', NULL),
('oden-croquette', 'Oden Croquette', 'おでんコロッケ', 'kanto', 'tokyo', 'A genius street food invention! Classic oden ingredients (like daikon and fish cake) are chopped, mixed with potato, breaded, and deep-fried.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains wheat, egg, soy, fish', 150, 300, 'Published', ARRAY['Quick bite']::text[], 'Not vegetarian', 'Not halal', true, 'Born in the lively shopping streets (shotengai) of Shinagawa, this dish takes traditional winter comfort food and turns it into a portable, crispy snack.', NULL, 'It captures the deep, dashi-broth flavor of oden in every bite, meaning you don''t even need any sauce to enjoy it!', ARRAY['Potatoes, oden broth, breadcrumbs']::text[], 'oh-den koh-rok-keh', NULL),
('edomae-anago', 'Edomae Anago', '江戸前穴子', 'kanto', 'tokyo', 'Incredibly soft, simmered conger eel (anago) brushed with a sweet soy glaze. It melts in your mouth and is a staple of traditional Tokyo sushi.', ARRAY['Summer']::text[], ARRAY['local specialty']::text[], 'Contains fish, soy, wheat', 1500, 4000, 'Published', ARRAY['Dine-in']::text[], 'Not vegetarian', 'Not halal', true, 'Shinagawa was historically a coastal post town on the Tokaido road, famous for catching fresh Anago in the shallow waters of Tokyo Bay (Edomae).', NULL, 'Unlike freshwater eel (unagi) which is rich and fatty, saltwater anago is prized for its incredibly fluffy, light, and delicate texture!', ARRAY['Conger eel, soy sauce, sugar, mirin']::text[], 'eh-doh-mah-eh ah-nah-goh', NULL),
('harajuku-crepe', 'Harajuku Crepe', '原宿クレープ', 'kanto', 'tokyo', 'A massive, cone-shaped crepe stuffed to the brim with fresh fruits, whipped cream, ice cream, and sweet syrups. A true Tokyo pop-culture icon!', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains gluten, dairy, egg', 500, 1000, 'Published', ARRAY['Vegetarian', 'Quick bite']::text[], 'Verified vegetarian', 'Not halal', true, 'Originating in the late 1970s on Takeshita Street, these portable, highly photogenic desserts became the ultimate symbol of Harajuku youth culture.', NULL, 'There are dozens of flavor combinations available, but the classic ''Strawberry Choco Cream'' remains the undisputed favorite among locals and tourists!', ARRAY['Wheat flour, milk, eggs, whipped cream, strawberries, chocolate sauce']::text[], 'hah-rah-joo-koo koo-reh-poo', NULL),
('omoide-yokocho-yakitori', 'Omoide Yokocho Yakitori', '焼き鳥（思い出横丁）', 'kanto', 'tokyo', 'Smoky, charcoal-grilled chicken skewers enjoyed in a narrow, lantern-lit alleyway. It''s an atmospheric and delicious dive into Tokyo''s nightlife.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains meat (chicken), soy (if tare glaze used)', 150, 500, 'Published', ARRAY['Quick bite', 'Dine-in']::text[], 'Not vegetarian', 'Not halal', true, 'Memory Lane'' (Omoide Yokocho) started as a post-war black market. Today, it retains its gritty, Showa-era charm, packed with tiny, bustling yakitori stalls.', NULL, 'The alley is also affectionately known by locals as ''Piss Alley,'' a cheeky nod to its rough-and-tumble post-war origins!', ARRAY['Chicken cuts (thigh, skin, cartilage), salt, tare (soy sauce, mirin, sugar)']::text[], 'yah-kee-toh-ree', NULL),
('ogikubo-ramen', 'Ogikubo Ramen', '荻窪ラーメン', 'kanto', 'tokyo', 'A classic Tokyo-style ramen featuring a clear, soy-sauce-based broth made from pork bones and dried sardines, served with curly noodles.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains gluten, pork, fish, soy', 800, 1500, 'Published', ARRAY['Dine-in']::text[], 'Not vegetarian', 'Not halal', true, 'Ogikubo is considered one of the birthplaces of Tokyo ramen, with many historic shops dating back to the post-war period still operating today.', NULL, 'The broth''s distinct flavor comes from ''niboshi'' (dried baby sardines), giving it a deeply savory, umami-rich taste without being heavy!', ARRAY['Ramen noodles, soy sauce, pork bones, dried sardines, pork chashu']::text[], 'oh-gee-koo-boh rah-men', NULL),
('chanko-nabe', 'Chanko Nabe', 'ちゃんこ鍋', 'kanto', 'tokyo', 'A massive, protein-packed hot pot loaded with chicken, meatballs, tofu, and vegetables, simmered in a rich dashi broth.', ARRAY['Winter']::text[], ARRAY['local specialty']::text[], 'Contains meat, fish (broth), soy, wheat', 2000, 6000, 'Published', ARRAY['Dine-in']::text[], 'Not vegetarian', 'Not halal', true, 'This is the official diet of sumo wrestlers! Sumida Ward, home to the Ryogoku Kokugikan sumo stadium, is packed with restaurants serving this hearty dish.', NULL, 'Traditional Chanko Nabe avoids using beef or pork because a sumo wrestler must always stand on two legs—never on all fours like a cow or pig!', ARRAY['Chicken broth, chicken meatballs (tsukune), tofu, napa cabbage, mushrooms, leeks']::text[], 'chahn-koh nah-beh', NULL),
('chomeiji-sakura-mochi', 'Chomeiji Sakura Mochi', '長命寺桜もち', 'kanto', 'tokyo', 'A delicate pink crepe wrapped around sweet red bean paste, enveloped in a pickled cherry blossom leaf. A quintessential taste of Japanese spring.', ARRAY['Spring']::text[], ARRAY['local specialty']::text[], 'Vegan, Contains wheat', 200, 500, 'Published', ARRAY['Vegetarian', 'Halal', 'Quick bite', 'Dine-in']::text[], 'Verified vegetarian', 'Verified halal', true, 'Created in the 18th century by a gatekeeper at Chomeiji Temple who was inspired by the falling cherry blossom leaves along the Sumida River.', NULL, 'The pickled leaf is entirely edible! Its slight saltiness perfectly balances the sweet red bean paste inside.', ARRAY['Wheat flour, smooth red bean paste (koshian), pickled cherry leaves, sugar']::text[], 'choh-may-jee sah-koo-rah moh-chee', NULL),
('daikan-mochi', 'Daikan Mochi', '代官餅', 'kanto', 'tokyo', 'Freshly pounded, ultra-soft rice cakes served steaming hot, typically coated in sweet roasted soybean flour (kinako), red bean, or grated radish.', ARRAY['Only available Dec 15-16 and Jan 15-16']::text[], ARRAY['local specialty']::text[], 'Dairy-free. Contains soy. Anko and Kinako flavors are naturally gluten-free.', 700, 800, 'Published', ARRAY['Vegetarian', 'Quick bite']::text[], 'Verified vegetarian', 'Not halal', true, 'This famous mochi is only available once a year during the historic Boro-ichi (rag market) festival, a Setagaya tradition dating back over 400 years.', NULL, 'The lines to buy this festival treat can take hours, but eating the warm, stretchy mochi in the crisp winter air is absolutely worth it!', ARRAY['Glutinous rice (mochigome), red beans (azuki), roasted soybean flour (kinako), daikon radish, green onions, soy sauce, sugar.']::text[], 'dye-kahn mo-chee', NULL),
('okura-daikon', 'Okura Daikon', '大蔵大根', 'kanto', 'tokyo', 'A traditional, large white radish from Tokyo. It is prized for its crisp texture and ability to absorb savory broths when simmered in winter dishes.', ARRAY['Winter (November to February)']::text[], ARRAY['local specialty']::text[], 'Vegan and Gluten-free (as a base ingredient).', 300, 1200, 'Published', ARRAY['Vegetarian', 'Halal']::text[], 'Verified vegetarian', 'Verified halal', true, 'Cultivated in the Okura area of Setagaya since the Edo period, it is one of the designated ''Edo Tokyo Vegetables,'' preserving the city''s agricultural roots.', NULL, 'This heirloom radish was almost lost to modern, uniformly shaped varieties, but was revived by dedicated local farmers to preserve its superior flavor!', ARRAY['Okura Daikon']::text[], 'oh-koo-rah dye-kohn', NULL),
('ningyoyaki', 'Ningyoyaki', '人形焼', 'kanto', 'tokyo', 'Tiny, fluffy sponge cakes shaped like traditional symbols and filled with sweet red bean paste. A warm, comforting street food classic.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains wheat, egg, dairy', 100, 1000, 'Published', ARRAY['Vegetarian', 'Quick bite']::text[], 'Verified vegetarian', 'Not halal', true, 'Originating in the Ningyocho (Doll Town) area, these sweets are now the signature souvenir of Asakusa, baked fresh near the famous Senso-ji Temple.', NULL, 'In Asakusa, they are traditionally baked into four shapes: a five-story pagoda, a thunder lantern, a pigeon, and a thunder god!', ARRAY['Wheat flour, egg, sugar, red bean paste (anko)']::text[], 'neen-gyoh-yah-kee', NULL),
('dojo-nabe', 'Dojo Nabe', 'どぜう鍋', 'kanto', 'tokyo', 'A shallow iron pot filled with simmered loach (a small river fish), topped with a mountain of fresh green onions and cooked in a sweet soy broth.', ARRAY['Summer']::text[], ARRAY['local specialty']::text[], 'Contains fish, soy, wheat', 2000, 5000, 'Published', ARRAY['Dine-in']::text[], 'Not vegetarian', 'Not halal', true, 'This is a true taste of old Edo! Loach was an affordable, stamina-boosting protein for the working-class citizens of Tokyo during the samurai era.', NULL, 'The fish are traditionally simmered whole, bones and all, until they are so tender they practically melt in your mouth!', ARRAY['Loach (Dojo), soy sauce, sweet sake (mirin), green onions']::text[], 'doh-joh nah-beh', NULL),
('kaminari-okoshi', 'Kaminari Okoshi', '雷おこし', 'kanto', 'tokyo', 'A crispy, crunchy sweet snack made of puffed rice coated in syrup and mixed with peanuts. It''s Tokyo''s traditional answer to the rice crispy treat!', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Vegan, contains peanuts', 300, 1000, 'Published', ARRAY['Vegetarian', 'Quick bite']::text[], 'Verified vegetarian', 'Not halal', true, 'Sold outside Asakusa''s Kaminarimon (Thunder Gate) since the Edo period, the name ''Okoshi'' is a pun on the Japanese word for ''establishing a family or business.''', NULL, 'Because of the lucky pun in its name, it has been a popular good-luck souvenir in Tokyo for over 200 years!', ARRAY['Puffed rice, peanuts, sugar, mizuame (starch syrup)']::text[], 'kah-mee-nah-ree oh-koh-she', NULL),
('edo-style-tendon', 'Edo-style Tendon', '江戸前天丼', 'kanto', 'tokyo', 'A generous bowl of rice topped with crispy seafood tempura, heavily drizzled with a rich, dark, and sweet soy-based sauce.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains gluten, soy, fish, crustacean (shrimp)', 1500, 4000, 'Published', ARRAY['Dine-in']::text[], 'Not vegetarian', 'Not halal', true, 'Born in the bustling streets of Asakusa, Edo-style tempura traditionally uses sesame oil for frying, giving it a distinctively rich aroma and golden-brown color.', NULL, 'Unlike the light, crispy tempura served at high-end restaurants, downtown Tendon is meant to be hearty, saucy, and deeply satisfying!', ARRAY['Shrimp, white fish, wheat flour, sesame oil, soy sauce, sweet sake (mirin), rice']::text[], 'eh-doh-mah-eh ten-don', NULL),
('udora-yaki-udo-manju', 'Udora-yaki & Udo Manju', 'ウドラ焼き・うどまんじゅう', 'kanto', 'tokyo', 'Playful local sweets featuring ''Udora,'' a mascot inspired by the city''s famous Udo plant, filled with sweet bean paste and a hint of local flavor.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains wheat, egg, soy', 280, 400, 'Published', ARRAY['Vegetarian', 'Quick bite']::text[], 'Verified vegetarian', 'Not halal', true, 'These sweets were created to promote Tachikawa''s unique agricultural product, the Tokyo Udo, blending local farming heritage with modern kawaii (cute) culture.', NULL, 'The mascot ''Udora'' looks like a cute little monster made of a white asparagus-like vegetable, making these sweets a hit with kids!', ARRAY['Wheat flour, red bean paste, egg, Tokyo Udo, sugar']::text[], 'oo-doh-rah-yah-kee / oo-doh-mahn-joo', NULL),
('tachikawa-yakiton', 'Tachikawa Yakiton', '立川やきとん', 'kanto', 'tokyo', 'Skewers of grilled pork, heavily seasoned and cooked over charcoal. It''s the ultimate savory companion to a cold beer after a long day.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains pork, soy', 150, 600, 'Published', ARRAY['Quick bite', 'Dine-in']::text[], 'Not vegetarian', 'Not halal', true, 'Yakiton (grilled pork) has long been a staple of the lively izakaya culture around Tachikawa Station, serving commuters and locals alike.', NULL, 'While ''yakitori'' means grilled chicken, ''yakiton'' uses pork, and you can order incredibly specific cuts, from pork belly to cheek and liver!', ARRAY['Pork offal, soy sauce, mirin, sugar, salt']::text[], 'tah-chee-kah-wah yah-kee-ton', NULL),
('tachikawa-pudding', 'Tachikawa Pudding', '立川ぷりん', 'kanto', 'tokyo', 'A rich, creamy, and velvety custard pudding made with high-quality local eggs and milk, topped with a layer of bittersweet caramel.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains egg, dairy', 680, 700, 'Published', ARRAY['Vegetarian', 'Quick bite']::text[], 'Verified vegetarian', 'Not halal', true, 'Developed by local pastry chefs to showcase the high quality of dairy and eggs produced in the Tama region surrounding Tachikawa.', NULL, 'Japanese ''purin'' is firmer and richer than Western puddings, offering a satisfying, melt-in-your-mouth texture that locals obsess over!', ARRAY['Local eggs, milk, fresh cream, cane sugar, vanilla beans']::text[], 'tah-chee-kah-wah poo-reen', NULL),
('sakura-polvoron', 'Sakura Polvoron', '桜ぽるぼろん', 'kanto', 'tokyo', 'A crumbly, melt-in-your-mouth shortbread cookie infused with the delicate scent of cherry blossoms. It''s a sweet, floral taste of spring.', ARRAY['Spring']::text[], ARRAY['local specialty']::text[], 'Contains wheat, dairy, egg', 500, 1000, 'Published', ARRAY['Vegetarian', 'Quick bite']::text[], 'Verified vegetarian', 'Not halal', true, 'Developed by a ''Tama City Souvenir Project'' bringing together local universities, businesses, and the local government. It represents a collaborative effort to boost local pride.', NULL, 'Polvoron is originally a Spanish pastry, but this version adds a uniquely Japanese twist with the use of real cherry blossom petals!', ARRAY['Wheat flour, sugar, butter, salted Tama cherry blossoms']::text[], 'sah-koo-rah poh-roo-boh-ron', NULL),
('tama-no-sanpomichi', 'Tama no Sanpomichi', '多摩の散歩道', 'kanto', 'tokyo', 'A beautifully crafted assortment of baked sweets, designed to evoke the feeling of taking a relaxing stroll through the green parks of Tama City.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains wheat, soy', 300, 800, 'Published', ARRAY['Vegetarian', 'Quick bite']::text[], 'Verified vegetarian', 'Not halal', true, 'These sweets were created as a premium local souvenir, reflecting the city''s reputation as a leafy, peaceful suburban retreat from central Tokyo.', NULL, 'Sanpomichi'' translates to ''promenade'' or ''walking path,'' making these sweets the perfect companion for a picnic in one of Tama''s many parks!', ARRAY['Local wheat flour, sweet miso, sugar']::text[], 'tah-mah no sahn-poh-mee-chee', NULL),
('ponpoko-udon', 'Ponpoko Udon', 'ぽんぽこうどん', 'kanto', 'tokyo', 'A comforting bowl of udon noodles topped with crispy tempura bits (tanuki) and local vegetables, served in a warm, savory broth.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains wheat, soy, fish (in broth)', 500, 1200, 'Published', ARRAY['Dine-in']::text[], 'Not vegetarian', 'Not halal', true, 'The name ''Ponpoko'' pays homage to the famous Studio Ghibli film ''Pom Poko,'' which is set in Tama City and features the local raccoon dogs (tanuki).', NULL, 'In Japanese food culture, udon topped with crunchy tempura flakes is always called ''Tanuki Udon,'' making this a perfect cinematic food pun!', ARRAY['Tama City wheat flour, water, salt, dashi broth']::text[], 'pon-poh-koh oo-don', NULL),
('tsukishima-monjayaki', 'Tsukishima Monjayaki', '月島もんじゃ焼き', 'kanto', 'tokyo', 'Tokyo''s famous savory, runny pancake! A batter of cabbage, seafood, and meat is poured onto a hot iron grill, and you eat it directly off the griddle.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains wheat, soy, seafood, meat (varies)', 1000, 2500, 'Published', ARRAY['Dine-in']::text[], 'Not vegetarian', 'Not halal', true, 'Tsukishima is the undisputed mecca of Monjayaki, with an entire street (Monja Street) dedicated to this fun, interactive post-war dish.', NULL, 'It might not look like the prettiest dish when it''s cooking, but the crispy, caramelized edges you scrape off the grill are absolutely addictive!', ARRAY['Wheat flour, dashi broth, shredded cabbage, mentaiko (spicy cod roe), mochi, cheese']::text[], 'tsoo-kee-she-mah mon-jah-yah-kee', NULL),
('tsukiji-tamagoyaki', 'Tsukiji Tamagoyaki', '築地の玉子焼き', 'kanto', 'tokyo', 'A thick, slightly sweet, and incredibly juicy rolled omelet, served piping hot on a stick for easy snacking while exploring the market.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains egg, fish (dashi), soy', 100, 300, 'Published', ARRAY['Quick bite']::text[], 'Not vegetarian', 'Not halal', true, 'These omelets were traditionally made by specialist shops in the Tsukiji Market to supply high-end sushi restaurants across Tokyo.', NULL, 'Making the perfect Tamagoyaki requires immense skill, using a specialized rectangular copper pan to roll the delicate layers of egg!', ARRAY['Eggs, dashi (soup stock), sugar, soy sauce, mirin']::text[], 'tsoo-kee-jee no tah-mah-goh-yah-kee', NULL),
('ginza-omurice', 'Ginza Omurice', '銀座のオムライス', 'kanto', 'tokyo', 'A flawless, fluffy French-style omelet draped over savory chicken-and-ketchup fried rice, often topped with a rich demi-glace sauce.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains egg, poultry, wheat, soy', 1500, 3000, 'Published', ARRAY['Dine-in']::text[], 'Not vegetarian', 'Not halal', true, 'Omurice is a classic example of ''Yoshoku'' (Western-influenced Japanese cuisine), pioneered in the upscale, modern restaurants of Ginza in the early 20th century.', NULL, 'Slicing open the perfectly cooked omelet to reveal the creamy, soft-scrambled eggs inside is a mesmerizing experience you have to see to believe!', ARRAY['Eggs, white rice, chicken, onions, ketchup, butter']::text[], 'geen-zah no oh-moo-rye-soo', NULL),
('jindaiji-soba', 'Jindaiji Soba', '深大寺そば', 'kanto', 'tokyo', 'Nutty, aromatic buckwheat noodles served chilled on a bamboo mat or hot in a savory broth, surrounded by the lush greenery of an ancient temple.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Vegan, Contains buckwheat, soy', 800, 1500, 'Published', ARRAY['Vegetarian', 'Dine-in']::text[], 'Verified vegetarian', 'Not halal', true, 'With a history of over 400 years, this soba was originally made using the pure spring waters surrounding the historic Jindaiji Temple in Chofu.', NULL, 'There are over 20 historic soba shops clustered around the temple, making it one of the best noodle-hopping destinations in Tokyo!', ARRAY['Buckwheat flour, wheat flour, spring water, soy sauce, dashi']::text[], 'jeen-dye-jee soh-bah', NULL),
('seiro-soba', 'Seiro Soba', 'せいろそば', 'kanto', 'tokyo', 'Elegant, chilled buckwheat noodles served on a traditional wooden steamer box (seiro), accompanied by a highly refined, soy-based dipping sauce.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Vegan, contains buckwheat, soy', 700, 1500, 'Published', ARRAY['Vegetarian', 'Dine-in']::text[], 'Verified vegetarian', 'Not halal', true, 'Chiyoda Ward, the historic center of Edo (Tokyo), is home to some of the oldest and most prestigious soba restaurants in Japan, preserving samurai-era recipes.', NULL, 'To eat it like a true Tokyoite, you should only dip the bottom third of the noodles into the sauce to appreciate the natural aroma of the buckwheat!', ARRAY['Buckwheat flour, water, dashi']::text[], 'say-roh soh-bah', NULL),
('mori-soba', 'Mori Soba', 'もりそば', 'kanto', 'tokyo', 'A simple, minimalist dish of cold buckwheat noodles piled high on a plate or basket, designed to highlight the pure, earthy flavor of the noodles.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Vegan, contains buckwheat, soy', 600, 1200, 'Published', ARRAY['Vegetarian', 'Dine-in']::text[], 'Verified vegetarian', 'Not halal', true, 'In the Edo period, ''Mori'' (piled) soba became the fast food of the bustling capital, offering a quick, cheap, and delicious meal for busy workers.', NULL, 'At the end of the meal, you mix the remaining dipping sauce with hot noodle-boiling water (sobayu) to drink as a comforting, savory tea!', ARRAY['Buckwheat flour, water, dashi']::text[], 'moh-ree soh-bah', NULL),
('shio-daifuku', 'Shio Daifuku', '塩大福', 'kanto', 'tokyo', 'A soft, chewy rice cake filled with sweet red bean paste, balanced with a distinct, savory touch of salt in the mochi wrapper.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Vegan, Gluten-free', 150, 400, 'Published', ARRAY['Vegetarian', 'Halal', 'Quick bite']::text[], 'Verified vegetarian', 'Verified halal', true, 'Famous in the Sugamo area (known as the ''Harajuku for Grandmas''), this sweet perfectly balances salt and sugar, a flavor profile loved by older generations.', NULL, 'The addition of salt actually enhances the sweetness of the red bean paste, making it a sophisticated and highly addictive treat!', ARRAY['Glutinous rice, red beans, salt, sugar']::text[], 'shee-oh dye-foo-koo', NULL),
('otafuku-mame', 'Otafuku Mame', 'お多福豆', 'kanto', 'tokyo', 'Large, premium broad beans simmered slowly in sugar and soy sauce until they are incredibly tender, sweet, and glossy.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Vegan, contains soy', 500, 1200, 'Published', ARRAY['Vegetarian', 'Halal']::text[], 'Verified vegetarian', 'Verified halal', true, 'These sweet beans are a traditional Japanese confection, often associated with good fortune and sold in historic shopping districts like Sugamo.', NULL, 'Otafuku'' translates to ''much good fortune,'' making these sweet beans a popular gift for New Year''s and other celebratory occasions!', ARRAY['Broad beans, sugar, soy sauce']::text[], 'oh-tah-foo-koo mah-meh', NULL),
('tsubaki-oil', 'Tsubaki Oil', '椿油', 'kanto', 'tokyo', 'Pure, golden camellia oil extracted from the seeds of the island''s abundant Tsubaki flowers. It is used both as a gourmet cooking oil and a beauty product.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Vegan, Gluten-free', 1000, 3000, 'Published', ARRAY['Vegetarian', 'Halal']::text[], 'Verified vegetarian', 'Verified halal', true, 'Toshima Island is covered in camellia trees, and producing this high-quality oil has been the island''s primary industry for centuries.', NULL, 'When used for frying tempura, Tsubaki oil makes the batter incredibly light and crispy, though it is considered a very luxurious and rare ingredient!', ARRAY['Camellia seeds']::text[], 'tsoo-bah-kee oy-roo', NULL),
('8-tier-soft-serve-daily-chico', '8-Tier Soft Serve - Daily Chico', '8段ソフトクリーム（デイリーチコ）', 'kanto', 'tokyo', 'A towering, gravity-defying ice cream cone featuring eight different flavors of soft serve stacked on top of each other!', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains dairy', 700, 900, 'Published', ARRAY['Vegetarian', 'Halal', 'Quick bite']::text[], 'Verified vegetarian', 'Verified halal', true, 'Located in the basement of the Nakano Broadway shopping center, this iconic dessert has been a beloved challenge for Tokyo''s youth and otaku culture for decades.', NULL, 'You have to eat it fast and keep it perfectly balanced, or this massive tower of ice cream will topple over!', ARRAY['Milk, sugar, various flavorings']::text[], 'hah-chee-dahn so-foo-toh koo-ree-moo', NULL),
('oyaki-refu-tei', 'Oyaki - Refu-tei', 'おやき（おやき処 れふ亭）', 'kanto', 'tokyo', 'A hot, round, pancake-like pastry stuffed with a variety of sweet or savory fillings, from classic red bean to rich custard cream.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains wheat, egg, dairy', 150, 300, 'Published', ARRAY['Vegetarian', 'Quick bite']::text[], 'Verified vegetarian', 'Not halal', true, 'Refu-tei is a legendary stall right outside Nakano Station, famous for its long lines and the comforting, sweet aroma that fills the air.', NULL, 'You can watch the staff expertly flip dozens of these treats on a massive custom iron griddle through the shop''s glass window!', ARRAY['Flour, eggs, sugar, various fillings']::text[], 'oh-yah-kee reh-foo-tay', NULL),
('kusaya', 'Kusaya', 'くさや', 'kanto', 'tokyo', 'A famously pungent dried fish, fermented in a special brine. It has a very strong aroma but rewards adventurous eaters with an incredibly rich, umami flavor.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains fish', 800, 2000, 'Published', ARRAY[]::text[], 'Not vegetarian', 'Not halal', true, 'Created centuries ago on the Izu Islands as a way to preserve fish using a continuously fermented brine (kusaya eki) that is passed down through generations.', NULL, 'Kusaya is often compared to blue cheese—the smell can be overpowering, but locals and gourmands absolutely adore its complex taste!', ARRAY['Flying fish or mackerel, kusaya brine']::text[], 'koo-sah-yah', NULL),
('asahi-karinto', 'Asahi Karinto', 'かりんとう (旭製菓)', 'kanto', 'tokyo', 'Deep-fried, crunchy dough sticks coated in a rich, dark brown sugar glaze. They are a classic, highly addictive Japanese tea-time snack.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains wheat, soy, sesame', 300, 1000, 'Published', ARRAY['Vegetarian', 'Quick bite']::text[], 'Verified vegetarian', 'Not halal', true, 'Asahi Seika has been specializing in these traditional sweets for decades, perfecting the balance of crunch and deep, caramelized sweetness.', NULL, 'While brown sugar is the classic flavor, they now make Karinto in dozens of modern flavors, including matcha, sesame, and even spicy pepper!', ARRAY['Wheat flour, yeast, oil, brown sugar (kokuto), white sugar, sesame']::text[], 'kah-reen-toh', NULL),
('nerima-daikon-takuan', 'Nerima Daikon Takuan', '練馬大根の沢庵漬け', 'kanto', 'tokyo', 'A legendary Tokyo specialty made from the rare, slender Nerima Daikon radish. These long white radishes are sun-dried on wooden racks and traditionally pickled in barrels with rice bran and salt. The result is a vibrant yellow, deeply savory pickle with an incredibly crisp and loud crunch that has been celebrated in Tokyo for centuries.', ARRAY['Winter']::text[], ARRAY['local specialty']::text[], 'Contains Rice Bran and Salt. Gluten-Free and Vegan.', 400, 800, 'Published', ARRAY['Vegetarian', 'Halal', 'Quick bite']::text[], 'Verified vegetarian', 'Verified halal', true, 'Cultivation began in Nerima during the Edo Period due to its deep, soft volcanic soil. It became so popular for winter preservation that it was heavily praised by the Shogun samurai government and local Tokyo citizens alike.', NULL, 'The original Nerima Daikon radish grows so deeply into the ground and becomes so firmly rooted that the town hosts an annual ''Radish Pulling Championship'' where people compete just to pull them out of the dirt!', ARRAY['Nerima Daikon radish, rice bran (nuka), salt, persimmon peels (for natural sweetness).']::text[], 'Neh-ree-mah Die-kon Tah-koo-ahn', NULL),
('nerima-daikon-manju', 'Nerima Daikon Manju', '練馬大根まんじゅう', 'kanto', 'tokyo', 'A clever and adorable sweet confection shaped exactly like a realistic **miniature Nerima Daikon radish**. Created by the 120-year-old historical shop **Okashitsukasa Kimura-ya**, this unique hybrid treat wraps traditional sweet red bean paste inside a smooth, rich outer coating of **white chocolate**. It is celebrated as one of the ward''s most creative gourmet gifts.', ARRAY['-']::text[], ARRAY['local specialty']::text[], 'Contains Wheat, Dairy, Soy, and Red Bean. Vegetarian-friendly.', 150, 300, 'Published', ARRAY['Vegetarian', 'Halal', 'Quick bite']::text[], 'Verified vegetarian', 'Verified halal', true, 'Invented in the year 2000 by the fourth-generation master chef of **Okashitsukasa Kimura-ya**. He wanted to design a fun, visual souvenir that younger travelers and children could easily enjoy while learning about the area''s agricultural history.', NULL, 'Wrapped in a soft, steamed dough made from freshly grated yam and rice flour, it yields gently to reveal a deeply satisfying, smooth red bean paste inside.', ARRAY['01 Soft Steamed Dough Base: A tender, elegant exterior crafted from a traditional blend of grated yam and jōyoko (rice flour), yielding a soft, steamed texture rather than a hard snap. | 02 Smooth Red Bean Center: Generously filled with homemade koshian (smooth, pureed sweet red bean paste) to provide a deep, earthy sweetness at its core. | 03 Hand-Crafted Finish: Carefully shaped by hand, gently steamed, and meticulously finished with a delicate touch of green nerikiri to complete the radish illusion.']::text[], 'Neh-ree-mah Die-kon Mahn-joo', NULL),
('nerima-daifuku', 'Nerima Daifuku', 'ねりま大福', 'kanto', 'tokyo', 'A soft, pillowy mochi rice cake that incorporates finely minced, salted Nerima radish leaves directly into the outer dough. Handcrafted by the famous Nerima Fugetsu-do confectionery house, the bits of green leaf add a beautiful emerald speckle and a faint hint of natural saltiness. This savory accent cuts through the sweetness of the rich red bean paste filling beautifully.', ARRAY['-']::text[], ARRAY['local specialty']::text[], 'Contains Glutinous Rice, Red Bean, and Salted Radish Leaves. Gluten-Free and Vegan.', 160, 200, 'Published', ARRAY['Vegetarian', 'Halal', 'Quick bite']::text[], 'Verified vegetarian', 'Verified halal', true, 'Created by Nerima Fugetsu-do (founded in 1963) as a way to use the entire radish plant sustainably. Instead of discarding the vitamin-packed radish greens, they pickled them in salt to create a brilliant new flavor profile for traditional mochi.', NULL, 'While standard daifuku mochi uses smooth sweet rice dough, this local version has a rustic texture because you can physically feel the tiny crunch of the salted green vegetable bits inside the soft casing!', ARRAY['Glutinous rice flour (mochiko), premium Hokkaido red bean paste, salted Nerima radish leaves, sugar.']::text[], 'Neh-ree-mah Die-foo-koo', NULL),
('nerima-sabl', 'Nerima Sablé', '練馬サブレ', 'kanto', 'tokyo', 'A crunchy, rich shortbread cookie meticulously baked into the exact geographical shape of Tokyo''s Nerima Ward! Handcrafted by the traditional bakery Chikushido, the recipe uses local Tokyo wheat flour mixed with dried, nutrient-rich local radish leaves. It is highly popular as an edible geography lesson and local souvenir.', ARRAY['-']::text[], ARRAY['local specialty']::text[], 'Contains Wheat, Butter, Eggs, and Sugar. Vegetarian-friendly.', 80, 120, 'Published', ARRAY['Vegetarian', 'Halal', 'Quick bite']::text[], 'Verified vegetarian', 'Verified halal', true, 'Developed by the master bakers at Chikushido (originally founded in 1932). They spent months testing the recipe so that the fragile jagged borders of the Nerima map shape wouldn''t break apart in the oven while baking.', NULL, 'The clear plastic wrapper of every single cookie comes printed with a mini-map layout of Nerima Ward, allowing users to look through the clear window and find exactly where their hotel or train station sits on the cookie!', ARRAY['Locally milled Tokyo wheat flour, rich butter, sugar, fresh eggs, ground dried Nerima radish leaves.']::text[], 'Neh-ree-mah Sah-boo-reh', NULL),
('hachioji-ramen', 'Hachioji Ramen', '八王子ラーメン', 'kanto', 'tokyo', 'A local ramen featuring a soy sauce broth, lard, and finely chopped raw onions.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains wheat, soy, pork', 600, 1000, 'Published', ARRAY['Dine-in']::text[], 'Not vegetarian', 'Not halal', true, 'The chopped onions add a refreshing sweetness that balances the rich lard.', NULL, 'Recognized as a distinct regional ramen style.', ARRAY['Noodles, soy broth, lard, chopped onions']::text[], 'hah-chee-oh-jee rah-men', NULL),
('hachijo-shochu', 'Hachijo Shochu', '八丈焼酎', 'kanto', 'tokyo', 'A unique island shochu often made from a blend of sweet potatoes and barley.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Vegan, Gluten-free', 1500, 4000, 'Published', ARRAY['Vegetarian', 'Halal']::text[], 'Verified vegetarian', 'Verified halal', true, 'The blending of grains gives it a distinctive, robust flavor.', NULL, 'Introduced by exiles sent to the island during the Edo period.', ARRAY['Sweet potatoes, barley, water']::text[], 'hah-chee-joh shoh-choo', NULL),
('hachijo-fruit-lemon', 'Hachijo Fruit Lemon', '八丈フルーツレモン', 'kanto', 'tokyo', 'An exceptionally large and sweet lemon grown on Hachijojima.', ARRAY['Winter']::text[], ARRAY['local specialty']::text[], 'Vegan, Gluten-free', 500, 1500, 'Published', ARRAY['Vegetarian', 'Halal', 'Quick bite']::text[], 'Verified vegetarian', 'Verified halal', true, 'It is sweet enough to be eaten whole, including the peel.', NULL, 'Often used in local jams, desserts, and drinks.', ARRAY['Hachijo Lemon']::text[], 'hah-chee-joh foo-roo-tsoo reh-mon', NULL),
('karuta-senbei-hamurin-senbei', 'Karuta Senbei / Hamurin Senbei', 'かるたせんべい・はむりんせんべい', 'kanto', 'tokyo', 'Crispy rice crackers featuring local motifs and the Hamura City mascot.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Vegan, contains soy', 300, 800, 'Published', ARRAY['Vegetarian', 'Halal', 'Quick bite']::text[], 'Verified vegetarian', 'Verified halal', true, 'A fun, edible souvenir representing the city of Hamura.', NULL, 'Flavored with traditional soy sauce.', ARRAY['Rice, soy sauce']::text[], 'kah-roo-tah sen-bay / hah-moo-reen sen-bay', NULL),
('hamura-no-seki', 'Hamura no Seki', '羽村の堰', 'kanto', 'tokyo', 'Not a food, but a historic dam on the Tama River that provides water to Tokyo.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'N/A', NULL, NULL, 'Published', ARRAY['Vegetarian']::text[], 'Verified vegetarian', 'Not halal', true, 'Built in 1653, it is the origin of the Tamagawa Aqueduct.', NULL, 'A vital piece of Tokyo''s historical infrastructure.', ARRAY['Water']::text[], 'hah-moo-rah no seh-kee', NULL),
('sakura-sable-sazareishi', 'Sakura Sable / Sazareishi', '桜サブレー・さざれ石', 'kanto', 'tokyo', 'Delicate cookies inspired by cherry blossoms and traditional stones.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains wheat, dairy, egg', 400, 1000, 'Published', ARRAY['Vegetarian', 'Halal', 'Quick bite']::text[], 'Verified vegetarian', 'Verified halal', true, 'Popular souvenirs during the spring viewing season.', NULL, 'Rich in butter and subtle sweetness.', ARRAY['Flour, butter, sugar']::text[], 'sah-koo-rah sah-boo-reh / sah-zah-reh-ee-she', NULL),
('noka-no-nidango', 'Noka no Nidango', '農家の煮ぃだんご', 'kanto', 'tokyo', 'Rustic flour dumplings simmered in a hearty vegetable and soy broth.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Vegan, contains wheat, soy', 500, 1200, 'Published', ARRAY['Vegetarian', 'Dine-in']::text[], 'Verified vegetarian', 'Not halal', true, 'A traditional, warming dish made by local farmers.', NULL, 'Often loaded with daikon, carrots, and taro.', ARRAY['Flour, seasonal vegetables, soy broth']::text[], 'noh-kah no nee-dahn-goh', NULL),
('wasanbon-kogei-kashi', 'Wasanbon Kogei Kashi', '和三盆工芸菓子', 'kanto', 'tokyo', 'Exquisitely crafted traditional sweets made from premium Wasanbon sugar.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Vegan, Gluten-free', 800, 2000, 'Published', ARRAY['Vegetarian', 'Halal', 'Quick bite']::text[], 'Verified vegetarian', 'Verified halal', true, 'Molded into seasonal shapes like flowers and leaves.', NULL, 'Known for melting instantly and elegantly in the mouth.', ARRAY['Wasanbon sugar']::text[], 'wah-sahn-bon koh-gay kah-she', NULL),
('higashimurayama-black-yakisoba', 'Higashimurayama Black Yakisoba', '東村山黒焼きそば', 'kanto', 'tokyo', 'A striking local yakisoba made with a dark sauce containing squid ink.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains wheat, soy, squid', 600, 1200, 'Published', ARRAY['Dine-in']::text[], 'Not vegetarian', 'Not halal', true, 'Created as a unique local B-grade gourmet dish.', NULL, 'The squid ink adds a deep, savory umami flavor.', ARRAY['Noodles, squid ink sauce, cabbage, pork']::text[], 'hee-gah-she-moo-rah-yah-mah koo-roh yah-kee-soh-bah', NULL),
('musashino-udon', 'Musashino Udon', '武蔵野うどん', 'kanto', 'tokyo', 'Extremely thick, firm, and chewy udon noodles served with a warm dipping broth.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains wheat, soy, fish (broth)', 700, 1500, 'Published', ARRAY['Dine-in']::text[], 'Not vegetarian', 'Not halal', true, 'A traditional staple of the Musashino plateau where wheat farming was prominent.', NULL, 'The broth often contains pork and leeks (Niku-jiru).', ARRAY['Wheat flour, water, pork, leeks, dashi']::text[], 'moo-sah-she-noh oo-don', NULL),
('higashiyamato-cha-udon', 'Higashiyamato Cha Udon', 'ひがしやまと茶うどん', 'kanto', 'tokyo', 'Udon noodles infused with local green tea, giving them a vibrant color and aroma.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Vegan, contains wheat, soy', 700, 1500, 'Published', ARRAY['Vegetarian', 'Dine-in']::text[], 'Verified vegetarian', 'Not halal', true, 'A creative local dish combining two regional specialties: wheat and tea.', NULL, 'Refreshing and slightly bitter.', ARRAY['Wheat flour, green tea powder, water']::text[], 'hee-gah-she-yah-mah-toh chah oo-don', NULL),
('sayama-tea', 'Sayama Tea', '狭山茶', 'kanto', 'tokyo', 'A highly regarded green tea known for its deep, rich flavor and thick leaves.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Vegan, Gluten-free', 1000, 3000, 'Published', ARRAY['Vegetarian', 'Halal', 'Quick bite']::text[], 'Verified vegetarian', 'Verified halal', true, 'There is a saying: ''Shizuoka for color, Uji for aroma, Sayama for taste.''', NULL, 'Grown in the Saitama and western Tokyo areas.', ARRAY['Green tea leaves']::text[], 'sah-yah-mah chah', NULL),
('hino-pears', 'Hino Pears', '日野の梨', 'kanto', 'tokyo', 'Sweet and juicy Japanese pears cultivated in Hino City.', ARRAY['Autumn']::text[], ARRAY['local specialty']::text[], 'Vegan, Gluten-free', 500, 2000, 'Published', ARRAY['Vegetarian', 'Halal', 'Quick bite']::text[], 'Verified vegetarian', 'Verified halal', true, 'Hino has a long history of fruit cultivation thanks to its good water sources.', NULL, 'Popular varieties include Kosui and Hosui.', ARRAY['Japanese pear']::text[], 'hee-noh no nah-she', NULL),
('hinode-tomato', 'Hinode Tomato', '日の出トマト', 'kanto', 'tokyo', 'Sun-ripened, intensely sweet tomatoes grown in Hinode Town.', ARRAY['Summer']::text[], ARRAY['local specialty']::text[], 'Vegan, Gluten-free', 300, 1000, 'Published', ARRAY['Vegetarian', 'Halal', 'Quick bite']::text[], 'Verified vegetarian', 'Verified halal', true, 'Grown using pure local water and careful farming techniques.', NULL, 'Often sold directly at local farmers'' markets.', ARRAY['Tomato']::text[], 'hee-noh-deh toh-mah-toh', NULL),
('yuzu-hinohara-black-tea', 'Yuzu / Hinohara Black Tea', 'ゆず・ひのはら紅茶', 'kanto', 'tokyo', 'A fragrant local black tea blended with the citrusy aroma of yuzu.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Vegan, Gluten-free', 600, 1500, 'Published', ARRAY['Vegetarian', 'Halal', 'Quick bite']::text[], 'Verified vegetarian', 'Verified halal', true, 'Hinohara Village is Tokyo''s only village (excluding islands) and produces excellent tea.', NULL, 'A perfect warming drink for the mountain climate.', ARRAY['Black tea leaves, yuzu citrus']::text[], 'yoo-zoo / hee-noh-hah-rah koh-chah', NULL),
('hinohara-potatoes', 'Hinohara Potatoes', 'ひのはらじゃがいも', 'kanto', 'tokyo', 'Small, dense, and highly flavorful potatoes grown on the steep slopes of Hinohara.', ARRAY['Autumn']::text[], ARRAY['local specialty']::text[], 'Vegan, Gluten-free', 300, 800, 'Published', ARRAY['Vegetarian', 'Halal']::text[], 'Verified vegetarian', 'Verified halal', true, 'The steep terrain and climate make them firmer and sweeter than regular potatoes.', NULL, 'Often boiled and eaten with a sweet miso glaze.', ARRAY['Potatoes']::text[], 'hee-noh-hah-rah jah-gye-moh', NULL),
('apollo-pan', 'Apollo Pan', 'アポロパン', 'kanto', 'tokyo', 'A nostalgic, sweet local bread roll.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains wheat, dairy, egg', 150, 300, 'Published', ARRAY['Vegetarian', 'Quick bite']::text[], 'Verified vegetarian', 'Not halal', true, 'A beloved local bakery staple.', NULL, 'Named during the space race era.', ARRAY['Flour, sugar, yeast']::text[], 'ah-poh-roh pahn', NULL),
