('ogai-mochi', 'Ogai Mochi', '鴎外餅', 'kanto', 'tokyo', 'A traditional sweet created in honor of the famous author Mori Ogai.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Vegan, Gluten-free', 200, 600, 'Published', ARRAY['Vegetarian', 'Halal', 'Quick bite']::text[], 'Verified vegetarian', 'Verified halal', true, 'Ogai lived in the area and is a celebrated local historical figure.', NULL, 'Often enjoyed with green tea.', ARRAY['Glutinous rice, sweet bean paste']::text[], 'oh-gye moh-chee', NULL),
('kanchorou-ginkgo-sable', 'Kanchorou Ginkgo Sable', '観潮楼のいちょうサブレ', 'kanto', 'tokyo', 'Buttery cookies shaped like the ginkgo leaves from Ogai''s former residence.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains wheat, dairy, egg', 400, 1000, 'Published', ARRAY['Vegetarian', 'Halal', 'Quick bite']::text[], 'Verified vegetarian', 'Verified halal', true, 'Kanchorou was the name of Mori Ogai''s house.', NULL, 'A literary-themed souvenir.', ARRAY['Flour, butter, sugar']::text[], 'kahn-choh-roh no ee-choh sah-boo-reh', NULL),
('machida-silk-melon', 'Machida Silk Melon', 'まちだシルクメロン', 'kanto', 'tokyo', 'A highly cultivated, incredibly sweet and juicy premium melon from Machida.', ARRAY['Summer']::text[], ARRAY['local specialty']::text[], 'Vegan, Gluten-free', 3000, 10000, 'Published', ARRAY['Vegetarian', 'Halal', 'Quick bite']::text[], 'Verified vegetarian', 'Verified halal', true, 'Grown using advanced hydroponic techniques in Machida.', NULL, 'Known for its melt-in-the-mouth ''silk'' texture.', ARRAY['Melon']::text[], 'mah-chee-dah shee-roo-koo meh-ron', NULL),
('hengo-dango', 'Hengo Dango', 'ヘンゴだんご', 'kanto', 'tokyo', 'A rustic local dumpling made from partially crushed rice.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Vegan, Gluten-free', 150, 400, 'Published', ARRAY['Vegetarian', 'Halal', 'Quick bite']::text[], 'Verified vegetarian', 'Verified halal', true, 'A traditional homemade snack from the Tama region.', NULL, 'The texture is uniquely chewy.', ARRAY['Rice, sweet soy glaze']::text[], 'hen-goh dahn-goh', NULL),
('sakuyuri-no-kinton', 'Sakuyuri no Kinton', 'サクユリのきんとん', 'kanto', 'tokyo', 'A delicate wagashi made using the edible bulbs of the Sakuyuri lily.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Vegan', 300, 800, 'Published', ARRAY['Vegetarian', 'Halal', 'Quick bite']::text[], 'Verified vegetarian', 'Verified halal', true, 'Sakuyuri is a large lily native to the Izu Islands.', NULL, 'Has a subtle, elegant sweetness.', ARRAY['Lily bulb, sugar, white bean paste']::text[], 'sah-koo-yoo-ree no keen-ton', NULL),
('hayaki', 'Hayaki', 'はやき', 'kanto', 'tokyo', 'A fast-fermented local pickle, offering a sharp, crisp bite.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Vegan, Gluten-free', 200, 500, 'Published', ARRAY['Vegetarian', 'Halal']::text[], 'Verified vegetarian', 'Verified halal', true, 'A staple side dish in local households.', NULL, 'Provides a refreshing contrast to heavy meals.', ARRAY['Radish, salt, vinegar']::text[], 'hah-yah-kee', NULL),
('jinenjo-karukan-manju', 'Jinenjo Karukan Manju', '自然薯かるかん饅頭', 'kanto', 'tokyo', 'A spongy, airy steamed sweet made with grated wild mountain yam.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Vegan', 200, 600, 'Published', ARRAY['Vegetarian', 'Halal', 'Quick bite']::text[], 'Verified vegetarian', 'Verified halal', true, 'The wild yam gives the dough a uniquely light and springy texture.', NULL, 'Filled with smooth red bean paste.', ARRAY['Wild yam, rice flour, sugar, red bean paste']::text[], 'jee-nen-joh kah-roo-kahn mahn-joo', NULL),
('kiwi-amazake', 'Kiwi Amazake', 'キウイ甘酒', 'kanto', 'tokyo', 'A modern, fruity twist on traditional sweet fermented rice drink using local kiwis.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Vegan, Gluten-free', 400, 800, 'Published', ARRAY['Vegetarian', 'Halal', 'Quick bite']::text[], 'Verified vegetarian', 'Verified halal', true, 'A creative way to use the region''s agricultural products.', NULL, 'Non-alcoholic and highly nutritious.', ARRAY['Rice koji, kiwi fruit']::text[], 'kee-oo-ee ah-mah-zah-keh', NULL),
('azabu-juban-bean-snacks', 'Azabu Juban Bean Snacks', '麻布十番の豆菓子', 'kanto', 'tokyo', 'A wide variety of roasted beans and nuts coated in sweet or savory flavors.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Vegan, contains soy/peanuts', 400, 1500, 'Published', ARRAY['Vegetarian', 'Halal', 'Quick bite']::text[], 'Verified vegetarian', 'Verified halal', true, 'Sold at historic shops in the upscale yet traditional Azabu Juban area.', NULL, 'Flavors range from matcha and plum to curry and cheese.', ARRAY['Peanuts, soybeans, flour, various seasonings']::text[], 'ah-zah-boo joo-bahn no mah-meh-gah-she', NULL),
('akame-satoimo', 'Akame Satoimo', '赤芽さといも', 'kanto', 'tokyo', 'A variety of taro root known for its reddish buds and sticky, tender texture.', ARRAY['Autumn']::text[], ARRAY['local specialty']::text[], 'Vegan, Gluten-free', 300, 800, 'Published', ARRAY['Vegetarian', 'Halal']::text[], 'Verified vegetarian', 'Verified halal', true, 'A traditional ingredient in autumn stews.', NULL, 'Highly prized for its smooth texture when simmered.', ARRAY['Taro root']::text[], 'ah-kah-meh sah-toh-ee-moh', NULL),
('muroaji-ashitaba-smoked-fish', 'Muroaji Ashitaba Smoked Fish', 'むロアジあした葉燻製', 'kanto', 'tokyo', 'Local mackerel smoked using the leaves of the island''s native Ashitaba plant.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains fish', 800, 2000, 'Published', ARRAY[]::text[], 'Not vegetarian', 'Not halal', true, 'A specialty of the Izu Islands.', NULL, 'The Ashitaba imparts a unique, herbal smokiness to the fish.', ARRAY['Mackerel, Ashitaba leaves, salt']::text[], 'moo-roh-ah-jee ah-she-tah-bah koon-say', NULL),
('musashino-jigona-udon', 'Musashino Jigona Udon', '武蔵野地粉うどん', 'kanto', 'tokyo', 'Musashino udon made specifically with locally milled wheat flour for extra flavor.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains wheat, soy', 700, 1500, 'Published', ARRAY['Dine-in']::text[], 'Not vegetarian', 'Not halal', true, 'The local flour gives the noodles a stronger wheat aroma and rustic color.', NULL, 'Served with a hot, savory dipping broth.', ARRAY['Local wheat flour, water, dashi']::text[], 'moo-sah-she-noh jee-goh-nah oo-don', NULL),
('murayama-kate-udon', 'Murayama Kate Udon', '村山かてうどん', 'kanto', 'tokyo', 'A local variation of Kate Udon from the Murayama area, rich in seasonal toppings.', ARRAY['All year']::text[], ARRAY['local specialty']::text[], 'Contains wheat, soy', 800, 1500, 'Published', ARRAY['Dine-in']::text[], 'Not vegetarian', 'Not halal', true, 'A traditional meal to mark the end of the wheat harvest.', NULL, 'Often includes eggplant, spinach, and daikon.', ARRAY['Wheat flour, seasonal vegetables, dashi']::text[], 'moo-rah-yah-mah kah-teh oo-don', NULL),
('meguro-no-sanma', 'Meguro no Sanma', '目黒のさんま', 'kanto', 'tokyo', 'Charcoal-grilled Pacific saury, famously associated with Meguro through a classic rakugo story.', ARRAY['Autumn']::text[], ARRAY['local specialty']::text[], 'Contains fish', 500, 1500, 'Published', ARRAY['Dine-in']::text[], 'Not vegetarian', 'Not halal', true, 'Based on a famous comedic rakugo tale where a lord declares ''Saury is best in Meguro!''', NULL, 'Meguro hosts a massive Sanma Festival every autumn where thousands of fish are grilled and given away.', ARRAY['Pacific Saury (Sanma), salt']::text[], 'meh-goo-roh no sahn-mah', NULL)
